(() => {
  // (pictures only) the ground cleaned up where the top views showed it ragged: in each box the sand-grass edge smoothed, the colours of the sand
  // and the grass smoothed (blotches gone), read off the top views themselves (jmask.py); shadows, tyre tracks, asphalt, kerbs, water, things kept
  if (window.__JNROOT) Render.scene.remove(window.__JNROOT);
  const H = window.__H3, T = __game.race.track, sc = Render.scene, TX = Tex.all(), out = {}; sc.updateMatrixWorld(true);
  const sst = (a, b, x) => { const t = Math.max(0, Math.min(1, (x - a) / (b - a))); return t * t * (3 - 2 * t); }, gnd = (x, z) => H.ground(x, z);
  const matOf = (o) => Array.isArray(o.material) ? o.material[0] : o.material;
  const NR = H.roads.nord, NP = NR.P2, NHW = NR.wd / 2, RG = new Map(); NP.forEach((p, i) => { const k = Math.floor(p.x / 20) + ',' + Math.floor(p.z / 20); if (!RG.has(k)) RG.set(k, []); RG.get(k).push(i); });
  const dNord = (x, z) => { let b = 1e9; const cx = Math.floor(x / 20), cz = Math.floor(z / 20); for (let a = -1; a <= 1; a++) for (let c = -1; c <= 1; c++) for (const i of RG.get((cx + a) + ',' + (cz + c)) || []) { const j = Math.min(NP.length - 1, i + 1), A = NP[i], B = NP[j], dx = B.x - A.x, dz = B.z - A.z, t = Math.max(0, Math.min(1, ((x - A.x) * dx + (z - A.z) * dz) / (dx * dx + dz * dz || 1))); b = Math.min(b, Math.hypot(x - A.x - dx * t, z - A.z - dz * t)); } return b; };
  const dCirc = (x, z) => Math.abs(T.query(x, z).d);
  let mk = null; sc.traverse(o => { if (mk || !o.isMesh) return; const m = matOf(o); if (m && m.bumpMap && m.map && !m.transparent && m.vertexColors && m.type === 'MeshPhongMaterial') mk = m; });
  const G = new THREE.Group(); G.name = 'jn'; G.userData.keep = true; sc.add(G); window.__JNROOT = G;
  const nz1 = (x, z) => 0.5 + 0.25 * Math.sin(0.37 * x + 0.21 * z + 1.3) + 0.25 * Math.sin(0.23 * z - 0.31 * x + 0.4);
  const texMean = (tx) => { try { const im = tx.image, c = document.createElement('canvas'); c.width = c.height = 64; const g = c.getContext('2d'); g.drawImage(im, 0, 0, 64, 64); const d = g.getImageData(0, 0, 64, 64).data; const s = [0, 0, 0]; for (let i = 0; i < d.length; i += 4) { s[0] += d[i]; s[1] += d[i + 1]; s[2] += d[i + 2]; } return s.map(v => v / (d.length / 4) / 255); } catch (e) { return [1, 1, 1]; } };
  const TS = mk && mk.map ? mk.map : TX.makadam, TG = TX.grass, mS = texMean(TS), mG = texMean(TG); out.tm = [mS, mG].map(a => a.map(v => +v.toFixed(3)));
  // the sand's grain: the makadam texture at under half its contrast (a flat colour looks like plastic, the full texture shows its tiles)
  const lowTex = (tx, k) => { try { const c = document.createElement('canvas'); c.width = c.height = 256; const g = c.getContext('2d'); g.drawImage(tx.image, 0, 0, 256, 256); const D = g.getImageData(0, 0, 256, 256), d = D.data, m = [0, 0, 0]; for (let i = 0; i < d.length; i += 4) for (let j = 0; j < 3; j++) m[j] += d[i + j]; for (let j = 0; j < 3; j++) m[j] /= d.length / 4;
      for (let i = 0; i < d.length; i += 4) for (let j = 0; j < 3; j++) d[i + j] = Math.max(0, Math.min(255, m[j] + k * (d[i + j] - m[j]))); g.putImageData(D, 0, 0); const t = new THREE.CanvasTexture(c); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 4; return [t, m.map(v => v / 255)]; } catch (e) { return [null, [1, 1, 1]]; } };
  const [TSL, mSL] = lowTex(TS, 0.42);
  const dec = (b) => { const s = atob(b), a = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); return a; };
  const offRoad2 = (x, z) => dNord(x, z) > NHW - 1.5 && dCirc(x, z) > (T.w || 6) - 0.5;   // the roads' own band is wider than their asphalt: the asphalt, kerbs and lines are kept by the views' colours (jmask)
  const RS = [{"name": "tun5", "x0": -270, "z0": -52, "S": 0.5, "nx": 84, "nz": 100, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "mx2", "x0": -345, "z0": -275, "S": 0.5, "nx": 190, "nz": 190, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "mxL", "x0": -345, "z0": -100, "S": 0.5, "nx": 114, "nz": 184, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "m8b", "x0": -300, "z0": 150, "S": 0.5, "nx": 120, "nz": 130, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "ro2", "x0": -250, "z0": -365, "S": 0.5, "nx": 90, "nz": 80, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "farm3", "x0": -30, "z0": -335, "S": 0.5, "nx": 150, "nz": 70, "dy": 0.32, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "j4", "x0": -80, "z0": -250, "S": 0.5, "nx": 100, "nz": 100, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "mx5", "x0": -340, "z0": -25, "S": 0.5, "nx": 110, "nz": 100, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "bus5", "x0": -190, "z0": 25, "S": 0.5, "nx": 120, "nz": 110, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "m8", "x0": -205, "z0": 135, "S": 0.5, "nx": 90, "nz": 80, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "m9", "x0": -140, "z0": 215, "S": 0.5, "nx": 530, "nz": 200, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}, {"name": "m10", "x0": 120, "z0": 190, "S": 0.5, "nx": 450, "nz": 250, "dy": 0.0, "f": "", "p": "", "cs": "", "cg": ""}];
  const mkLayer = (r, A, Cf, tx, uvS, dy, po, ro) => { const nx = r.nx, nz = r.nz, pos = [], col = [], uv = [], idx = [], al = new Float32Array(nx * nz);
    for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) { const x = r.x0 + (i + 0.5) * r.S, z = r.z0 + (j + 0.5) * r.S, q = j * nx + i, a = A(q, x, z); al[q] = a; const c = Cf(q); pos.push(x, H.ground(x, z) + dy, z); col.push(c[0], c[1], c[2], a); uv.push(x / uvS, -z / uvS); }
    for (let j = 0; j < nz - 1; j++) for (let i = 0; i < nx - 1; i++) { const a = j * nx + i; if (al[a] + al[a + 1] + al[a + nx] + al[a + nx + 1] < 0.004) continue; idx.push(a, a + nx, a + 1, a + 1, a + nx, a + nx + 1); }
    if (!idx.length) return 0; const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); g.setAttribute('color', new THREE.Float32BufferAttribute(col, 4)); g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2)); g.setIndex(idx);
    const m = new THREE.MeshBasicMaterial({ map: tx, vertexColors: true, transparent: true, depthWrite: false, fog: false, polygonOffset: true, polygonOffsetFactor: po, polygonOffsetUnits: po });
    const me = new THREE.Mesh(g, m); me.renderOrder = ro; me.userData.keep = true; me.frustumCulled = false; G.add(me); return pos.length / 3; };
  out.jn = RS.map(r => { const f = dec(r.f), p = dec(r.p), cs = dec(r.cs), cg = dec(r.cg), ok = new Uint8Array(r.nx * r.nz);
    for (let j = 0; j < r.nz; j++) for (let i = 0; i < r.nx; i++) { const x = r.x0 + (i + 0.5) * r.S, z = r.z0 + (j + 0.5) * r.S; ok[j * r.nx + i] = p[j * r.nx + i] > 0 && offRoad2(x, z) ? 1 : 0; }
    const nG = mkLayer(r, (q) => ok[q] ? p[q] / 255 : 0, (q) => [cg[q * 3] / 255 / mG[0], cg[q * 3 + 1] / 255 / mG[1], cg[q * 3 + 2] / 255 / mG[2]], TG, 14, 0.30 + (r.dy || 0), -11, 3.2);
    const nS = mkLayer(r, (q, x, z) => ok[q] ? p[q] / 255 * sst(0.4, 0.6, f[q] / 255 + 0.08 * (nz1(x * 1.7, z * 1.7) - 0.5)) : 0, (q) => [cs[q * 3] / 255 / mSL[0], cs[q * 3 + 1] / 255 / mSL[1], cs[q * 3 + 2] / 255 / mSL[2]], TSL, 3, 0.32 + (r.dy || 0), -12, 3.3);
    return [r.name, nG, nS]; });
  window.__JN = (k) => { G.visible = k > 0; return k; };
  return JSON.stringify(out);
})()